pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != caller2);
        vm.assume(caller1 != address(0));
        vm.assume(caller2 != address(0));
        // Set initial owner to caller1
        vm.prank(c.owner());
        c.transferOwnership(caller1);
        // caller2 attempts transferOwnership
        vm.prank(caller2);
        bool ok;
        try c.transferOwnership(caller2) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            // Only the current owner can successfully change owner
            assertTrue(c.owner() == caller1 || c.owner() == caller2);
        } else {
            assertTrue(c.owner() == caller1);
        }
    }
}

