pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address originalOwner, address firstNewOwner, address secondNewOwner) public {
        vm.assume(originalOwner != firstNewOwner);
        vm.assume(firstNewOwner != secondNewOwner);
        vm.assume(originalOwner != secondNewOwner);

        // Set up the original owner and transfer ownerships
        c.transferOwnership(originalOwner);
        vm.prank(originalOwner);
        c.transferOwnership(firstNewOwner);
        vm.prank(firstNewOwner);
        c.transferOwnership(secondNewOwner);

        // After two successive transfers, owner() must equal the second new owner in the correct contract.
        // The buggy version sets owner to a fixed address after the first call, so the second call has no effect.
        assertTrue(c.owner() == secondNewOwner);
    }
}

