import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address initialOwner, address newOwnerX, address newOwnerY) public {
        vm.assume(initialOwner != address(0));
        vm.assume(newOwnerX != address(0));
        vm.assume(newOwnerY != address(0));
        vm.assume(newOwnerX != initialOwner);
        vm.assume(newOwnerY != newOwnerX);
        vm.assume(newOwnerY != initialOwner);
        // Set initial owner
        vm.prank(c.owner());
        c.transferOwnership(initialOwner);
        // Two consecutive ownership transfers by the current owner
        vm.startPrank(initialOwner);
        c.transferOwnership(newOwnerX);
        c.transferOwnership(newOwnerY);
        vm.stopPrank();
        // After two calls, the correct contract must have owner == newOwnerY; the bug sets owner to a fixed address on the first call and never changes it.
        assertTrue(c.owner() == newOwnerY);
    }
}

