import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // The owner of the newly deployed C is the address that deployed it (this contract).
        // We must be the owner to call transferOwnership, so we prank as ourselves.
        vm.assume(newOwner != address(c));
        vm.prank(address(this));
        c.transferOwnership(newOwner);
        // After the call, the owner should be newOwner in the correct contract,
        // but the buggy version sets it to a fixed address instead.
        assertEq(c.owner(), newOwner);
    }
}

