pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner) public {
        // Ensure the fuzzed owner is not the zero address (transferring ownership to zero would break the test setup logic, but we want the test to focus on the owned() call).
        vm.assume(owner != address(0));

        // We need the fuzzed address to be the owner so that the onlyOwner modifier passes.
        // Transfer ownership to this address. The default owner is the test contract itself (msg.sender in setUp()).
        c.transferOwnership(owner);

        // The owner calls owned()
        vm.prank(owner);
        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful call, the contract code must still exist.
        // If the call reverted for any reason, we don't care (it might be due to other issues, but the rule
        // is about successful calls). The buggy version selfdestructs, so the code size becomes zero.
        if (ok) {
            assertTrue(address(c).code.length > 0);
        } else {
            // If it reverted, we don't assert anything about code length because the call failed.
            // The reference never reverts for an owner, but we allow it for broader fuzz coverage.
            assertTrue(true);
        }
    }
}

