// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // 1. Admissible domain: caller is the current owner (otherwise the original 
        //    onlyOwner also reverts, making no semantic difference)
        vm.assume(caller == c.owner());
        // 2. Prank as the (current) owner and attempt to transfer ownership
        vm.prank(caller);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        // 3. The reference C must succeed and update owner to newOwner;
        //    the buggy M must revert because it inverts the require condition.
        assertTrue(ok && c.owner() == newOwner);
    }
}
